<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

int main() {
    long long a, b, n;
    cin >> a >> b >> n;
    long double a_val = a, b_val = b;
    long double min_diff = 1e9;
    long double base_ratio = a_val / b_val;
    long long best_num = 0, best_den = 1;
    for (long long i = 1; i <= n; ++i) {
        long long candidate_num = (a * i) / b;
        long double ratio = (double)candidate_num;
        long double diff1 = fabs(ratio / i - base_ratio);
        long double diff2 = fabs((ratio + 1.0) / i - base_ratio);
        if (diff1 < min_diff || (diff1 == min_diff && (i < best_den || (i == best_den && candidate_num < best_num)))) {
            min_diff = diff1;
            best_num = candidate_num;
            best_den = i;
        }
        if (diff2 < min_diff || (diff2 == min_diff && (i < best_den || (i == best_den && candidate_num + 1 < best_num)))) {
            min_diff = diff2;
            best_num = candidate_num + 1;
            best_den = i;
        }
        if (candidate_num > 0) {
            long double diff3 = fabs((candidate_num - 1.0) / i - base_ratio);
            if (diff3 < min_diff || (diff3 == min_diff && (i < best_den || (i == best_den && candidate_num - 1 < best_num)))) {
                min_diff = diff3;
                best_num = candidate_num - 1;
                best_den = i;
            }
        }
    }
    cout << best_num << "/" << best_den << endl;
    return 0;
}
